import { Effect } from "effect"

export interface ManifestParcel {
  readonly trackingNumber: string
  readonly destination: string
  readonly weightGrams: number
}

export interface ManifestExport {
  readonly parcels: ReadonlyArray<ManifestParcel>
  readonly separator: "," | ";"
  readonly batchId: string
}

export const exportManifest = (input: ManifestExport) =>
  Effect.sync(() => {
    const { parcels, separator, batchId } = input
    const encodeRow = (
      fields: ReadonlyArray<string>
    ): string =>
      fields.map((field) => {
        const escaped = field.replaceAll('"', '""')
        return field.includes(separator) || /["\r\n]/.test(field)
          ? `"${escaped}"`
          : field
      }).join(separator)

    const rows = [
      encodeRow(["Batch", batchId]),
      encodeRow(["Tracking number", "Destination", "Weight (g)"])
    ]

    for (const parcel of parcels) {
      rows.push(encodeRow([
        parcel.trackingNumber,
        parcel.destination,
        String(parcel.weightGrams)
      ]))
    }

    rows.push(encodeRow(["Parcel count", String(parcels.length)]))
    return rows.join("\r\n")
  })
